# (nome, grupo, repetivel, texto, etapas[2ª em diante], nota)
T = "todas"; S = "shinigami"; Q = "quincy"; H = "hollow"; P = "proibida"

def sobe(attr, art="seu", limites=("17", "18", "20")):
    return [
        f"{art.capitalize()} atributo de {attr} aumenta em mais 1, e o limite passa a ser {limites[0]}.",
        f"{art.capitalize()} atributo de {attr} aumenta em mais 1, e o limite passa a ser {limites[1]}.",
        f"{art.capitalize()} atributo de {attr} aumenta em mais 1, e o limite passa a ser {limites[2]}.",
        f"{art.capitalize()} atributo de {attr} aumenta em mais 1, e você soma o dobro da sua proficiência aos testes de resistência de {attr}.",
    ]

def custo(inicial, vals, sufixo="pontos de reiatsu"):
    return [f"o custo diminui para {v} {sufixo}." for v in vals]

